INSERT INTO orbit.roadmaps (id, name, external_identifier, source_name, source_url, description, priority_tier, last_verified_at) VALUES
    ('301270de-b75b-5d2e-9ae7-de8c317f2230', 'MLOps', 'mlops', 'roadmap.sh', 'https://roadmap.sh/mlops', 'Operationalising ML: pipelines, serving, monitoring, and platform on Kubernetes.', 1, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('8040845c-708a-5949-84f2-8afaf03ef4d9', 'Forward Deployed Engineer', 'forward-deployed-engineer', 'roadmap.sh', 'https://roadmap.sh/forward-deployed-engineer', 'Customer-facing engineering: scope, integrate, prototype, and debug in production.', 1, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('3d294480-20f1-5dc3-b1c8-fb88bd105d1f', 'LeetCode', 'leetcode', 'roadmap.sh', 'https://roadmap.sh/leetcode', 'Coding-interview problem solving: complexity, patterns, DP and graphs.', 1, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('5a1d0037-e1aa-55c3-8588-198aed260b62', 'System Design', 'system-design', 'roadmap.sh', 'https://roadmap.sh/system-design', 'Designing scalable, reliable distributed systems and articulating the trade-offs.', 1, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('6428fc2f-9df2-5137-957f-4ff286b7bc94', 'DevOps', 'devops', 'roadmap.sh', 'https://roadmap.sh/devops', 'Building and operating delivery platforms: Linux, containers, IaC, CI/CD, observability.', 2, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('71611b3f-6274-5d9c-92d6-c764cf09d5d4', 'DevSecOps', 'devsecops', 'roadmap.sh', 'https://roadmap.sh/devsecops', 'Security built into delivery: threat modeling, scanning, policy, supply chain.', 2, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('947e6282-2b62-5394-836f-4100eccfd74c', 'AI Engineer', 'ai-engineer', 'roadmap.sh', 'https://roadmap.sh/ai-engineer', 'Building applications on top of foundation models: RAG, agents, evaluation, serving.', 2, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('8536d400-72e2-516e-aa6c-7b9920340c11', 'Machine Learning', 'machine-learning', 'roadmap.sh', 'https://roadmap.sh/machine-learning', 'Classical and deep ML: math foundations, model families, training and evaluation.', 2, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('822449e1-2f3a-51f8-a5c9-38b25c9dc1f9', 'Frontend', 'frontend', 'roadmap.sh', 'https://roadmap.sh/frontend', 'Building for the browser: markup and styling, JavaScript/TypeScript, a framework, performance and a11y.', 3, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('ab4dd1d6-3e6a-5457-aa9e-99b9526a974a', 'Backend', 'backend', 'roadmap.sh', 'https://roadmap.sh/backend', 'Server-side systems: a language, HTTP APIs, databases, auth, caching and queues.', 3, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('bd0172b7-c6a2-510c-9c13-612fc6f049c6', 'Full Stack', 'full-stack', 'roadmap.sh', 'https://roadmap.sh/full-stack', 'End-to-end web: frontend, backend APIs, a database, auth, and deployment.', 3, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('9d1e4c53-0fa4-5078-9e55-9d02bf63327f', 'Blockchain', 'blockchain', 'roadmap.sh', 'https://roadmap.sh/blockchain', 'Blockchain engineering: cryptography, consensus, smart contracts, Solidity and the EVM.', 3, TIMESTAMPTZ '2026-09-08T00:00:00Z'),
    ('f7de045c-0c6f-5939-a56b-576f80c69468', 'Cyber Security', 'cyber-security', 'roadmap.sh', 'https://roadmap.sh/cyber-security', 'Defensive and offensive security: networks, crypto, appsec, pen testing, SecOps.', 3, TIMESTAMPTZ '2026-09-08T00:00:00Z')
